struct mm_struct *init_mm(struct mm_struct *mm, struct task_struct *p, struct user_namespace *user_ns)
{
    int err;

    if (!mm)
        return NULL;

    atomic_set(&mm->count, 1);
    mm->mmap = NULL;
    mm->mmap_cache = NULL;
    mm->mmap_lock = (spinlock_t)__SPIN_LOCK_UNLOCKED;
    mm->pgd = get_pgd();
    if (!mm->pgd) {
        return NULL;
    }

    mm->flags = 0;
    mm->def_flags = 0;
    mm->free_area_cache = NULL;
    mm->start_code = 0;
    mm->end_code = 0;
    mm->start_data = 0;
    mm->end_data = 0;
    mm->start_brk = 0;
    mm->brk = 0;
    mm->start_stack = 0;
    mm->arg_start = 0;
    mm->arg_end = 0;
    mm->env_start = 0;
    mm->env_end = 0;
    mm->saved_auxv = NULL;
    mm->cpu_vm_mask = 0;
    mm->context = 0;

    mm->user_ns = user_ns;
    get_user_ns(user_ns);

    err = setup_new_context(mm, p);
    if (err) {
        free_pgd(mm->pgd);
        return NULL;
    }

    return mm;
}

struct mm_struct *init_mm(struct mm_struct *mm, struct task_struct *p, struct user_namespace *user_ns)
{
    int err;

    /* Initialize memory mappings */
    err = init_mem_mapping(mm);
    if (err)
        return NULL;

    /* Initialize reference counts */
    atomic_set(&mm->mm_users, 1);
    atomic_set(&mm->mm_count, 1);

    /* Initialize locks */
    spin_lock_init(&mm->page_table_lock);

    /* Configure flags based on current process's state or use defaults */
    if (current->mm) {
        mm->flags = current->mm->flags;
    } else {
        mm->flags = MM_DEFAULT_FLAGS;
    }

    /* Allocate page tables */
    mm->pgd = allocate_page_tables();
    if (!mm->pgd)
        return NULL;

    /* Initialize a new context for the task */
    err = init_new_context(mm, p);
    if (err) {
        free_page_tables(mm->pgd);
        return NULL;
    }

    return mm;
}

struct mm_struct *init_mm(struct mm_struct *mm, struct task_struct *p, struct user_namespace *user_ns)
{
    int err;

    mm = kzalloc(sizeof(*mm), GFP_KERNEL);
    if (!mm)
        return NULL;

    mm->mmap = NULL;
    mm->mmap_cache = NULL;
    mm->get_unmapped_area = arch_get_unmapped_area;
    mm->unmap_area = arch_unmap_area;
    mm->mmap_lock = (spinlock_t)__SPIN_LOCK_UNLOCKED;
    atomic_set(&mm->mm_users, 1);
    atomic_set(&mm->mm_count, 1);
    mm->user_ns = get_user_ns(user_ns);

    err = arch_dup_mmap(p ? p->mm : NULL, mm);
    if (err) {
        put_user_ns(user_ns);
        kfree(mm);
        return NULL;
    }

    return mm;
}

struct mm_struct *init_mm(struct mm_struct *mm, struct task_struct *p, struct user_namespace *user_ns) {
    if (!mm)
        return NULL;

    /* Initialize memory mappings */
    mm->mmap = NULL;
    mm->mmap_cache = NULL;
    mm->mmap_next = NULL;

    /* Set up reference counts */
    atomic_set(&mm->count, 1);
    mm->flags = 0;

    /* Configure locks */
    spin_lock_init(&mm->page_table_lock);

    /* Set up the task and user namespace */
    mm->task = p;
    mm->user_ns = user_ns;

    /* Allocate page tables and initialize context */
    if (allocate_page_tables(mm) != 0) {
        return NULL;
    }

    if (init_context(mm) != 0) {
        free_page_tables(mm);
        return NULL;
    }

    return mm;
}
